import partsIndex from '../../circuits/parts-index.json' with { type: 'json' };
import type { DeviceKind, Part, PartKind } from './schematic-types';

export interface LibraryPart {
  id: string; name: string; kind: DeviceKind; category: string; description: string; package: string;
  terminals: string[]; trust: 'draft' | 'verified'; datasheet: string | null;
  ratings: Record<string, { value: number; unit: string }>;
}

// Generated by `python -m backend.parts_cli index`; CI checks it matches the validated part files.
export const LIBRARY_PARTS = partsIndex as unknown as LibraryPart[];
export const DEVICE_KINDS: DeviceKind[] = ['D', 'NMOS', 'PMOS', 'NPN', 'PNP', 'OPAMP', 'REG'];
const TERMINAL_LETTERS: Record<string, string> = {
  anode: 'A', cathode: 'K', drain: 'D', gate: 'G', source: 'S', collector: 'C', base: 'B', emitter: 'E',
  output: 'OUT', in_plus: '+', in_minus: '−', v_plus: 'V+', v_minus: 'V−', input: 'IN', ground_or_adjust: 'G/A',
};
const DEFAULT_TERMINALS: Record<DeviceKind, string[]> = {
  D: ['anode', 'cathode'], NMOS: ['drain', 'gate', 'source'], PMOS: ['drain', 'gate', 'source'],
  NPN: ['collector', 'base', 'emitter'], PNP: ['collector', 'base', 'emitter'],
  OPAMP: ['output', 'in_plus', 'in_minus', 'v_plus', 'v_minus'], REG: ['output', 'input', 'ground_or_adjust'],
};
const TERMINAL_COUNTS: Partial<Record<PartKind, 1 | 3 | 5>> = { GND: 1, PIN: 1, NMOS: 3, PMOS: 3, NPN: 3, PNP: 3, REG: 3, OPAMP: 5 };

export function isDeviceKind(kind: PartKind): kind is DeviceKind {
  return (DEVICE_KINDS as PartKind[]).includes(kind);
}

export function libraryPart(id: string | null | undefined): LibraryPart | undefined {
  return LIBRARY_PARTS.find(part => part.id === id);
}

export function partsOfKind(kind: DeviceKind): LibraryPart[] {
  return LIBRARY_PARTS.filter(part => part.kind === kind);
}

export function terminalCount(kind: PartKind): 1 | 2 | 3 | 5 {
  return TERMINAL_COUNTS[kind] ?? 2;
}

export function isTransistor(kind: PartKind): boolean {
  return kind === 'NMOS' || kind === 'PMOS' || kind === 'NPN' || kind === 'PNP';
}

/** The terminal paired with terminal 0 for a part's main voltage: V0 − V1, Vds / Vce, output vs ground or V−. */
export function voltageReferenceTerminal(kind: PartKind): 1 | 2 | 4 {
  if (kind === 'OPAMP') return 4;
  return terminalCount(kind) === 3 ? 2 : 1;  // single-terminal parts have no part voltage
}

/** Columns a measurement table needs: the most terminals any part in the circuit has (at least two). */
export function terminalColumns(parts: Part[]): number {
  return Math.max(2, ...parts.map(part => terminalCount(part.kind)));
}

/** A terminal reading, prefixed with its letter (D, G, S, A, K…) only for library devices. */
export function terminalReading(part: Part, terminal: number, reading: string): string {
  if (terminal >= terminalCount(part.kind)) return '—';
  return isDeviceKind(part.kind) || part.kind === 'PIN' ? terminalLetter(part, terminal) + ' ' + reading : reading;
}

/** Full terminal name for devices ("gate"), or the terminal number for ideal parts. */
export function terminalName(part: Part, terminal: number): string {
  if (part.kind === 'PIN') return 'pin';
  return isDeviceKind(part.kind) ? DEFAULT_TERMINALS[part.kind][terminal] : String(terminal);
}

/** One-letter label drawn beside a terminal: A/K, D/G/S, C/B/E, or 0/1. */
export function terminalLetter(part: Part, terminal: number): string {
  const name = terminalName(part, terminal);
  return TERMINAL_LETTERS[name] ?? name;
}
